import 'package:geolocator/geolocator.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../push_notifications.dart';

class OpenBackend {
OpenBackend._();static final instance=OpenBackend._();final SupabaseClient client=Supabase.instance.client;String? get userId=>client.auth.currentUser?.id;bool get isAuthenticated=>userId!=null;
Future<AuthResponse> registerEmail(String e,String p)=>client.auth.signUp(email:e.trim(),password:p);Future<AuthResponse> loginEmail(String e,String p)=>client.auth.signInWithPassword(email:e.trim(),password:p);Future<void> sendPhoneOtp(String p)async{}String _mockPhoneEmail(String p)=>'phone_${p.replaceAll(RegExp(r'\D'),'')}@mock.open.local';String _mockPhonePassword(String p)=>'OpenMock!${p.replaceAll(RegExp(r'\D'),'')}#123456';
Future<AuthResponse> verifyPhoneOtp(String p,String t)async{if(t.trim()!='123456')throw const AuthException('Mock kod hatalı');final e=_mockPhoneEmail(p),pw=_mockPhonePassword(p);try{return await client.auth.signInWithPassword(email:e,password:pw);}on AuthException catch(x){if(!x.message.toLowerCase().contains('invalid'))rethrow;}final r=await client.functions.invoke('mock-phone-auth',body:{'phone':p.trim(),'token':t.trim()});if(r.status<200||r.status>=300)throw AuthException('Mock telefon hesabı oluşturulamadı: ${r.data}');return client.auth.signInWithPassword(email:e,password:pw);}
Future<AuthResponse> startMockPhoneSession()=>client.auth.signInAnonymously();Future<bool> hasCompletedProfile()async{final id=userId;if(id==null)return false;final r=await client.from('profiles').select('profile_complete').eq('id',id).maybeSingle();return r?['profile_complete']==true;}Future<bool> hasProfile()async{final id=userId;if(id==null)return false;return await client.from('profiles').select('id').eq('id',id).maybeSingle()!=null;}Future<void> signOut()async{await PushNotifications.instance.disableCurrentUserTokens();await PushNotifications.instance.stop();await client.auth.signOut();}
Future<void> saveProfile(String n,String c,String g,{String country='',String district=''})async{if(n.trim().isEmpty||c.trim().isEmpty)throw ArgumentError('Ad ve konum zorunlu');await client.from('profiles').upsert({'id':_uid(),'display_name':n.trim(),'city':c.trim(),'country':country.trim(),'district':district.trim(),'gender':g});}
Future<List<Map<String,dynamic>>> saveLockQuestions(List<String> qs)async{final id=_uid(),q=qs.map((e)=>e.trim()).toList();if(q.length!=3||q.any((e)=>e.isEmpty))throw ArgumentError('3 geçerli soru seçilmeli');final rows=await client.from('profile_questions').upsert([for(var i=0;i<3;i++){'profile_id':id,'question':q[i],'position':i+1}],onConflict:'profile_id,position').select('id,question,position').order('position');await client.from('profiles').update({'profile_complete':true}).eq('id',id);return List<Map<String,dynamic>>.from(rows);}
int _age(dynamic v){final d=DateTime.tryParse(v?.toString()??'');if(d==null)return -1;final n=DateTime.now();var a=n.year-d.year;if(n.month<d.month||(n.month==d.month&&n.day<d.day))a--;return a;}bool _genderMatches(String p,dynamic gender){p=p.trim().toLowerCase();final g=(gender??'').toString().toLowerCase();if(p.isEmpty||p=='herkes')return true;if(p.startsWith('kad'))return g.startsWith('kad')||g=='female'||g=='woman';if(p.startsWith('erk'))return g.startsWith('erk')||g=='male'||g=='man';return true;}
Future<Position?> _refreshPosition()async{try{if(!await Geolocator.isLocationServiceEnabled())return null;var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.denied||p==LocationPermission.deniedForever)return null;final x=await Geolocator.getCurrentPosition(locationSettings:const LocationSettings(accuracy:LocationAccuracy.medium,timeLimit:Duration(seconds:10)));await client.from('profiles').update({'latitude':x.latitude,'longitude':x.longitude}).eq('id',_uid());return x;}catch(_){return null;}}
Future<List<Map<String,dynamic>>> discover()async{final id=_uid();final sr=await client.from('user_settings').select('looking_for,min_age,max_age,max_distance_km').eq('user_id',id).limit(1);final s=sr.isEmpty?<String,dynamic>{}:Map<String,dynamic>.from(sr.first),pref=(s['looking_for']??'Herkes').toString(),min=(s['min_age'] as num?)?.toInt()??18,max=(s['max_age'] as num?)?.toInt()??80,maxKm=(s['max_distance_km'] as num?)?.toDouble()??50;var pos=await _refreshPosition();if(pos==null){final me=await client.from('profiles').select('latitude,longitude').eq('id',id).maybeSingle(),lat=(me?['latitude'] as num?)?.toDouble(),lng=(me?['longitude'] as num?)?.toDouble();if(lat!=null&&lng!=null)pos=Position(longitude:lng,latitude:lat,timestamp:DateTime.now(),accuracy:0,altitude:0,altitudeAccuracy:0,heading:0,headingAccuracy:0,speed:0,speedAccuracy:0);}final blocked=await client.from('user_blocks').select('blocked_id').eq('blocker_id',id);final blockedIds=blocked.map((e)=>e['blocked_id'].toString()).toSet();final data=await client.from('profiles').select('id,display_name,birth_date,bio,city,country,district,gender,avatar_url,gallery_urls,interests,is_online,is_verified,account_paused,latitude,longitude,profile_questions(id,question,position)').eq('profile_complete',true).neq('id',id).limit(100);final out=<Map<String,dynamic>>[];for(final raw in List<Map<String,dynamic>>.from(data)){final p=Map<String,dynamic>.from(raw);if(blockedIds.contains(p['id'].toString())||p['account_paused']==true||!_genderMatches(pref,p['gender']))continue;final a=_age(p['birth_date']);if(a>=0&&(a<min||a>max))continue;final lat=(p['latitude'] as num?)?.toDouble(),lng=(p['longitude'] as num?)?.toDouble();if(pos!=null){if(lat==null||lng==null)continue;final km=Geolocator.distanceBetween(pos.latitude,pos.longitude,lat,lng)/1000;if(km>maxKm)continue;p['distance_km']=km;}out.add(p);if(out.length>=30)break;}return out;}
Future<void> sendKey(String r,String q,String a)async{a=a.trim();if(a.isEmpty)throw ArgumentError('Cevap boş olamaz');await client.rpc('send_key_request',params:{'p_receiver':r,'p_question':q,'p_answer':a});}Future<List<Map<String,dynamic>>> incomingKeys()async=>List<Map<String,dynamic>>.from(await client.from('key_requests').select('id,sender_id,answer,status,created_at,profiles!key_requests_sender_id_fkey(display_name,avatar_url),profile_questions(question)').eq('receiver_id',_uid()).order('created_at',ascending:false));Future<List<Map<String,dynamic>>> outgoingKeys()async=>List<Map<String,dynamic>>.from(await client.from('key_requests').select('id,receiver_id,answer,status,created_at,profiles!key_requests_receiver_id_fkey(display_name,avatar_url),profile_questions(question)').eq('sender_id',_uid()).order('created_at',ascending:false));Future<int> pendingKeyCount()async{return (await client.from('key_requests').select('id').eq('receiver_id',_uid()).eq('status','pending')).length;}Future<void> rejectKey(String id)=>client.from('key_requests').update({'status':'rejected','responded_at':DateTime.now().toUtc().toIso8601String()}).eq('id',id).eq('receiver_id',_uid()).eq('status','pending');Future<String> acceptKey(String id)async=>(await client.rpc('accept_key_request',params:{'p_request':id})).toString();
Future<List<Map<String,dynamic>>> activeMatches()async{final me=_uid();return List<Map<String,dynamic>>.from(await client.from('matches').select('id,user_a,user_b,created_at').or('user_a.eq.$me,user_b.eq.$me').eq('active',true).order('created_at',ascending:false));}Stream<List<Map<String,dynamic>>> messageStream(String id)=>client.from('messages').stream(primaryKey:['id']).eq('match_id',id).order('created_at').map((r)=>List<Map<String,dynamic>>.from(r));Future<void> markMessagesRead(String id)=>client.rpc('mark_match_messages_read',params:{'p_match':id});Future<int> unreadMessageCount()async{final me=_uid(),ms=await activeMatches();var n=0;for(final m in ms){n+=(await client.from('messages').select('id').eq('match_id',m['id']).neq('sender_id',me).isFilter('read_at',null)).length;}return n;}Future<Map<String,dynamic>?> lastMessage(String matchId)async{final r=await client.from('messages').select('body,sender_id,read_at,created_at').eq('match_id',matchId).order('created_at',ascending:false).limit(1);return r.isEmpty?null:Map<String,dynamic>.from(r.first);}Future<int> unreadForMatch(String id)async=>(await client.from('messages').select('id').eq('match_id',id).neq('sender_id',_uid()).isFilter('read_at',null)).length;
Future<void> sendMessage(String id,String text)async{final b=text.trim();if(b.isEmpty)return;if(b.length>2000)throw ArgumentError('Mesaj en fazla 2000 karakter olabilir');final me=_uid(),m=await client.from('matches').select('id').eq('id',id).eq('active',true).or('user_a.eq.$me,user_b.eq.$me').maybeSingle();if(m==null)throw StateError('Bu eşleşmeye mesaj gönderemezsin');await client.from('messages').insert({'match_id':id,'sender_id':me,'body':b});}Future<void> unmatch(String id)=>client.rpc('unmatch',params:{'p_match':id});Future<void> blockUser(String id)=>client.rpc('block_user',params:{'p_user':id});Future<void> reportUser(String id,String reason,{String? matchId})=>client.from('user_reports').insert({'reporter_id':_uid(),'reported_id':id,'match_id':matchId,'reason':reason.trim().isEmpty?'Diğer':reason.trim()});String _uid(){final id=userId;if(id==null)throw StateError('Supabase oturumu gerekli');return id;}
}
